<script setup lang="ts">
import {ref} from 'vue'
import {request} from '../services/api'
const emit=defineEmits<{close:[]}>()
const email=ref(''),code=ref(''),password=ref(''),confirm=ref(''),challenge=ref(''),error=ref(''),message=ref(''),busy=ref(false),until=ref(0)
async function run(send:boolean){if(busy.value)return;busy.value=true;error.value='';message.value='';try{if(send&&Date.now()<until.value)throw Error('请在60秒后重发');if(!send&&password.value!==confirm.value)throw Error('两次密码不一致');const r=await request(send?'/auth/mail/challenge':'/auth/mail/reset',{method:'POST',body:JSON.stringify(send?{email:email.value,purpose:'reset'}:{email:email.value,new_password:password.value,proof:{challenge_id:challenge.value,code:code.value}})});if(send){challenge.value=r.challenge_id;until.value=Date.now()+60000;message.value='若该邮箱关联可用账号，将收到验证码。'}else{message.value='密码已修改，请返回登录。';password.value='';confirm.value='';code.value=''}}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><section class="card password-recovery"><h2>找回密码</h2><form @submit.prevent="run(false)"><label>已验证邮箱<input v-model="email" type="email" required></label><button type="button" :disabled="busy" @click="run(true)">发送找回验证码</button><label>验证码<input v-model="code" inputmode="numeric" maxlength="6" required></label><label>新密码<input v-model="password" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label><label>确认新密码<input v-model="confirm" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label><p v-if="error" role="alert" class="err">{{error}}</p><p v-if="message" role="status">{{message}}</p><button :disabled="busy||!challenge">验证并重置密码</button><button type="button" :disabled="busy" @click="emit('close')">返回登录</button></form></section></template>
<style scoped>
.password-recovery{color:var(--text)}h2{font-size:20px;margin:0 0 18px}form,label{display:grid;gap:10px}form{gap:14px}label{font-size:13px;font-weight:600}input{width:100%;box-sizing:border-box;min-width:0;min-height:44px;padding:10px 12px;border:1px solid var(--border);border-radius:11px;background:var(--card);color:var(--text);font:inherit;font-size:16px}button{min-height:44px;border:1px solid var(--border);border-radius:12px;padding:10px 14px;background:var(--soft);color:var(--primary-deep);font:inherit;font-size:13px;font-weight:600}button[type=submit],button:not([type]){background:var(--primary);border-color:var(--primary);color:white}button:disabled{opacity:.5;cursor:not-allowed}p{font-size:13px;line-height:1.7;margin:0}.err{color:#a04e43}
</style>
